success.beforeFullFileContent:
"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ReferenceLine,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  BAND_COUNTS,
  COUNTRY_LATEST,
  ETUI_DECADE,
  HEADLINE,
  SOURCE_NOTE,
  TREND_SERIES,
  VIZ_MARKERS,
  bumpRows,
  filterByRegion,
  scatterPairs,
  type IntensityBand,
  type Region,
} from "@/data/oecd-strike-days-per-1-000-employees-2026-data";

// viz-types: horizontal intensity ladder, multi-line trend, diverging bump bars, baseline-vs-recent scatter, intensity-band donut | layout: default

type PanelId = "ladder" | "trend" | "bump" | "scatter" | "bands";

type Horizon = "latest" | "avg2015_19" | "avg2020_21" | "avg2022_24";

type RegionFilter = "all" | Region;

const COLORS = {
  high: "#b91c1c",
  elevated: "#c2410c",
  moderate: "#0369a1",
  low: "#0f766e",
  minimal: "#94a3b8",
  bumpUp: "#b91c1c",
  bumpDown: "#0f766e",
  navy: "#0f172a",
  grid: "#e2e8f0",
  can: "#dc2626",
  fin: "#2563eb",
  fra: "#7c3aed",
  gbr: "#0891b2",
  deu: "#64748b",
  esp: "#ea580c",
  nor: "#0d9488",
  chl: "#ca8a04",
  kor: "#4f46e5",
  aus: "#059669",
  swe: "#db2777",
  usa: "#1e3a8a",
};

const TREND_COLOR: Record<string, string> = {
  CAN: COLORS.can,
  FIN: COLORS.fin,
  FRA: COLORS.fra,
  GBR: COLORS.gbr,
  DEU: COLORS.deu,
  ESP: COLORS.esp,
  NOR: COLORS.nor,
  CHL: COLORS.chl,
  KOR: COLORS.kor,
  AUS: COLORS.aus,
  SWE: COLORS.swe,
  USA: COLORS.usa,
};

const PANEL_OPTIONS: { id: PanelId; label: string }[] = [
  { id: "ladder", label: "Intensity ladder" },
  { id: "trend", label: "Country trends" },
  { id: "bump", label: "Post-2022 bump" },
  { id: "scatter", label: "Baseline vs recent" },
  { id: "bands", label: "Intensity bands" },
];

const REGION_OPTIONS: { id: RegionFilter; label: string }[] = [
  { id: "all", label: "All regions" },
  { id: "europe", label: "Europe" },
  { id: "north-america", label: "N. America" },
  { id: "latam", label: "LatAm" },
  { id: "asia-pacific", label: "Asia-Pacific" },
  { id: "other", label: "Other" },
];

const HORIZON_OPTIONS: { id: Horizon; label: string }[] = [
  { id: "latest", label: "Latest year" },
  { id: "avg2015_19", label: "2015???19 avg" },
  { id: "avg2020_21", label: "2020???21 avg" },
  { id: "avg2022_24", label: "2022???24 avg" },
];

function bandColor(band: IntensityBand): string {
  return COLORS[band];
}

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
  testId,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
  testId?: string;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2" data-testid={testId}>
