        </div>
      ) : null}

      {panel === "bump" ? (
        <div data-viz={VIZ_MARKERS.panelBump}>
          <ChartCard
            title="Did 2022???24 exceed 2015???19?"
            subtitle="?? days per 1,000 (recent avg ??? baseline avg). Red = hotter than late-2010s baseline."
          >
            <ResponsiveContainer width="100%" height={Math.max(320, bumpData.length * 30)}>
              <BarChart
                data={bumpData}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
