                />
                <Bar dataKey="delta" radius={[0, 4, 4, 0]}>
                  {bumpData.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
